// Catalog data: fetched at runtime from data/mods.json (generated by scripts/build.mjs).

export const SHORT_TITLES = {
  core: 'Core',
  security: 'Guardrails',
  git: 'Git',
  cost: 'Cost & Context',
  productivity: 'Productivity',
  quality: 'Quality',
  observability: 'Panes',
  prompting: 'Prompting',
  notifications: 'Notifications',
  memory: 'Memory',
  team: 'Team & Docs',
}

export const ICON_IDS = new Set(Object.keys(SHORT_TITLES))

const TIERS = {
  simple: { label: 'Essential', bars: 1 },
  complex: { label: 'Advanced', bars: 3 },
}

export function tierOf(tier) {
  return TIERS[tier] ?? { label: tier ? tier[0].toUpperCase() + tier.slice(1) : 'Mod', bars: 2 }
}

export function shortTitle(category) {
  return SHORT_TITLES[category.id] ?? category.title
}

export function iconHref(categoryId) {
  return `#i-${ICON_IDS.has(categoryId) ? categoryId : 'core'}`
}

export function iconSvg(categoryId, className = 'icon') {
  return `<svg class="${className}" aria-hidden="true"><use href="${iconHref(categoryId)}"/></svg>`
}

export function installCommand(name, marketplace = 'claude-mods') {
  return `/plugin install ${name}@${marketplace}`
}

export function sourceUrl(name, repository) {
  return `https://github.com/${repository}/tree/main/mods/${encodeURIComponent(name)}`
}

export function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch])
}

let pending = null

export function loadCatalog() {
  pending ??= fetch('data/mods.json', { credentials: 'same-origin' })
    .then(response => {
      if (!response.ok) throw new Error(`mods.json: ${response.status}`)
      return response.json()
    })
    .then(normalise)
  return pending
}

function normalise(raw) {
  const repository = raw.repository || 'plagemes/claude-mods'
  const categories = (raw.categories ?? []).map(c => ({ ...c, short: shortTitle(c) }))
  const byId = new Map(categories.map(c => [c.id, c]))
  const mods = (raw.mods ?? []).map((m, index) => ({
    ...m,
    index,
    keywords: m.keywords ?? [],
    commands: m.commands ?? [],
    categoryInfo: byId.get(m.category) ?? { id: m.category, title: m.category, short: m.category, tagline: '' },
  }))
  return { repository, marketplace: raw.marketplace, categories, mods, byName: new Map(mods.map(m => [m.name, m])) }
}
